<h5 class="mb-4">{{ $title }}</h5><div class="row g-3"><div class="col-md-6"><label class="form-label">{{ $nameLabel }} <span class="text-danger ms-1">*</span></label><input type="text" class="form-control" name="name" value="{{ $nameValue ?? '' }}" required></div><div class="col-md-6"><label class="form-label">{{ $unitLabel }}</label><input type="text" class="form-control" name="unit" value="{{ $unitValue ?? '' }}" placeholder="Ví dụ: kg, cái, đôi" required></div><div class="col-md-6"><label class="form-label">Đơn giá</label><input type="text" class="form-control" name="price" placeholder="25,000 VNĐ" required></div><div class="col-12"><label class="form-label">Ghi chú</label><textarea class="form-control" name="description" rows="3"></textarea></div></div><div class="d-flex justify-content-end gap-2 mt-4"><button type="submit" class="btn btn-primary">Cập nhật</button></div>
